// clang-format on

static int64_t gcd(int64_t a, int64_t b) {
    while (b != 0) {
        int64_t temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

static int64_t NChooseRFormula(int n, int r) {
    int64_t result = 1;
    for (int i = 1; i <= r; i++) {
        int64_t num = n - i + 1;
        int64_t den = i;
        int64_t g = gcd(num, den);

        num /= g;
        den /= g;

        // Divide first to prevent intermediate overflow
        result /= den;

        // Check if the upcoming multiplication will overflow a signed 64-bit
        // integer
        if (result > INT64_MAX / num) {
            return -1;  // Overflow
        }

        result *= num;
    }
    return result;
}

int64_t NChooseR(int n, int r) {
    if (n < 0 || r < 0) return -1;
    if (n < r) return 0;

    // Exploit symmetry to maximize cache hits and bound r.
    // This guarantees r will never exceed 32 if n <= 64, fitting in CACHE_COLS.
    if (r > n - r) {
        r = n - r;
    }

    // 3. Fallback to formula for numbers outside the pre-computed bounds
    if (n >= CACHE_ROWS) {
        return NChooseRFormula(n, r);
    }

    return choose_cache[n][r];
}
